export type GuideText = typeof GUIDE_EN;

// assets/ sits two levels above both src/i18n and dist/i18n, so dev and the built bot read the same files.
const DIR = join(dirname(fileURLToPath(import.meta.url)), "..", "..", "assets", "i18n", "guide");
const cache = new Map<Lang, GuideText>();

export function guideText(lang: Lang): GuideText {
  const hit = cache.get(lang);
  if (hit) return hit;
  const file = join(DIR, `${lang}.json`);
  const t = lang !== "en" && existsSync(file) ? { ...GUIDE_EN, ...(JSON.parse(readFileSync(file, "utf8")) as Partial<GuideText>) } : GUIDE_EN;
  cache.set(lang, t);
  return t;
}
